// Stand-in for the environment sniffing every emscripten bundle does at the top
// of its glue code. brotli@1.3.3 -- reached through parquetjs, which d2e's
// analytics-svc imports -- is the concrete package this models. Its
// `build/encode.js` opens with
//
//   var t = "object" === typeof window;                       // IS_WEB
//   var u = "function" === typeof importScripts;              // IS_WORKER
//   var v = "object" === typeof process && "function" === typeof require
//           && !t && !u;                                      // IS_NODE
//
// and, when neither IS_NODE nor IS_SHELL holds, reaches for an emscripten
// `Browser` object its build dead-code-eliminated, throwing
// `ReferenceError: Browser is not defined` while being required. brotli itself
// is not imported here: its emscripten heap trips the test worker's memory
// limit, which would make this test fail for an unrelated reason.
export default {
  window: typeof window,
  importScripts: typeof importScripts,
  process: typeof process,
  // The branch brotli resolves to. Must be "node".
  environment: "object" === typeof window
    ? "web"
    : "function" === typeof importScripts
    ? "worker"
    : "object" === typeof process
    ? "node"
    : "shell",
};
